'use strict';

// MODULES //

var isnan = require( '@stdlib/math-base-assert-is-nan' );
var incrmae = require( '@stdlib/stats-incr-mae' );


// MAIN //

/**
* Returns an accumulator function which incrementally computes the mean absolute error, ignoring `NaN` values.
*
* @returns {Function} accumulator function
*
* @example
* var accumulator = incrnanmae();
*
* var m = accumulator();
* // returns null
*
* m = accumulator( 2.0, 3.0 );
* // returns 1.0
*
* m = accumulator( NaN, 2.0 );
* // returns 1.0
*
* m = accumulator( -5.0, NaN );
* // returns 1.0
*
* m = accumulator( NaN, NaN );
* // returns 1.0
*
* m = accumulator( -5.0, 2.0 );
* // returns 4.0
*
* m = accumulator();
* // returns 4.0
*/
function incrnanmae() {
	var mae = incrmae();
	return accumulator;

	/**
	* If provided input values, the accumulator function returns an updated mean absolute error. If not provided input values, the accumulator function returns the current mean absolute error.
	*
	* @private
	* @param {number} [x] - input value
	* @param {number} [y] - input value
	* @returns {(number|null)} mean absolute error or null
	*/
	function accumulator( x, y ) {
		if ( arguments.length === 0 ) {
			return mae();
		}
		if ( isnan( x ) || isnan( y ) ) {
			return mae();
		}
		return mae( x, y );
	}
}


// EXPORTS //

module.exports = incrnanmae;
